"""100 situations rédigées individuellement ; les relances sont des exemples.

Références de travail créées pour cette évaluation, sans attribution à des annales.
Les étiquettes de justesse sont réservées au banc de test, jamais au dialogue.
"""

CHAPITRE = "17 — Série de réels ou de complexes"


def cas(numero, famille, titre, enonce, reference, initiale, statut, relance,
        justifiee, persistante, blocage, objectif):
    return {
        "id": f"K{numero:03d}", "famille": famille, "titre": titre,
        "chapitre": CHAPITRE, "enonce": enonce, "reference": reference,
        "reponse_initiale": initiale, "statut_initial": statut,
        "relance_exemple": relance, "objectif_relance": objectif,
        "reactions": {
            "justifiee": {"eleve": justifiee,
                "attendu": "Tenir compte de la justification donnée, accepter ses formulations équivalentes et poursuivre sans refaire le même défi."},
            "erreur_persistante": {"eleve": persistante,
                "attendu": "Cibler le point mathématique encore erroné avec une question plus concrète, sans validation complaisante ni simple verdict."},
            "blocage": {"eleve": blocage,
                "attendu": "Réduire la difficulté de la relance avec un seul indice utilisable ; laisser ensuite répondre l'élève."},
        },
        "critere_specifique": objectif,
        "temps_eleve_secondes": None,
        "provenance": "Scénario synthétique X-IA ; référence à relire par un enseignant.",
    }


